/**
 * Adapter — the IV-bolus sparse composite anchor (sparse-iv-bolus-anchor F1 / F3–F5).
 *
 * Fixture: `files/07_iv_bolus_sparse.csv` + `07_iv_bolus_sparse-reference.json`, generated by
 * sci-comp `regen-sparse-fixture.R` block 4 (simulated destructive IV-bolus composites; PKNCA
 * 0.12.1 `pk.calc.c0` / `pk.calc.auciv` oracle). The PO mouse fixture is the no-change control.
 *
 * `goldens/sparse-iv-anchor-0.11.0.json` pins TODAY's numbers, captured on sci-comp 0.11.0
 * before the anchor landed (architect 9): every IV composite's decision fingerprint and every
 * composite's full `SparseGroupResult` numbers. Generation: with no golden the capture test
 * returns its capture (base64 JSON) as the test result; read it with `grok test --csv`.
 */

import * as grok from 'datagrok-api/grok';
import * as DG from 'datagrok-api/dg';
import {category, test, expect, before} from '@datagrok-libraries/test/src/test';

import {computeSparseNca, sparseCompositeUnits} from '../adapter/sparse-nca';
import type {SparseGroupResult, SparseNcaResult} from '../adapter/sparse-nca';
import {computeDecisionFingerprint} from '../adapter/fingerprint';
import {c0ShareLine, configureSparseNcaGrid} from '../views/results-view';
import {computePipeline, COMPOSITE_SUBJECT} from '../pipeline/pipeline-compute';
import {detectPipelineMapping} from '../pipeline/pipeline-mapping';
import {loadFixture} from './test-utils';
import GOLDEN from './goldens/sparse-iv-anchor-0.11.0.json';

const TIMEOUT = 120000;
const FIXTURE_PATH_PREFIX = 'System:AppData/Nca';

/** Load a 04 / 07-layout sparse CSV as the `computeSparseNca` input frame: Conc in mg/L, a BOOL
 *  BLQ flag, body weight in kg (the units the fixtures' references use). */
export async function loadSparseFrame(file: string): Promise<DG.DataFrame> {
  const src = DG.DataFrame.fromCsv(await grok.dapi.files.readAsText(`${FIXTURE_PATH_PREFIX}/${file}`));
  const n = src.rowCount;
  const concNg = src.col('Conc_ng_mL')!; const blq = src.col('BLQ')!; const bwG = src.col('BodyWeight_g')!;
  src.columns.add(DG.Column.fromFloat64Array('Conc', Float64Array.from({length: n},
    (_, i) => (concNg.isNone(i) ? 0 : Number(concNg.get(i))) / 1000)));
  src.columns.add(DG.Column.fromList(DG.COLUMN_TYPE.BOOL, 'BLQflag',
    Array.from({length: n}, (_, i) => blq.getString(i).trim().toLowerCase() === 'true')));
  src.columns.add(DG.Column.fromFloat64Array('BodyWeight_kg', Float64Array.from({length: n},
    (_, i) => (bwG.isNone(i) ? NaN : Number(bwG.get(i))) / 1000)));
  return src;
}

/** The one sparse run of these tests: the fixture's dose groups as composites, on `route`. */
export function runSparse(df: DG.DataFrame, route: string, lloq: number): SparseNcaResult {
  return computeSparseNca(df, {
    concCol: 'Conc', nominalTimeCol: 'NominalTime_hr', animalIdCol: 'MouseID', blqCol: 'BLQflag',
    doseCol: 'Dose_mg_kg', bodyWeightCol: 'BodyWeight_kg', samplingTypeCol: 'SamplingType',
    groupCol: 'Dose_mg_kg', route, concUnit: 'mg/L', lloq, bootstrapIterations: 200,
  });
}

/** A JSON-safe number: NaN / ±Infinity as strings. */
const num = (v: number): number | string => (Number.isFinite(v) ? v : String(v));
const ci = (b: SparseGroupResult['bootstrapCl']): unknown =>
  ({estimate: num(b.estimate), ciLow: num(b.ciLow), ciHigh: num(b.ciHigh), method: b.method,
    suppressed: b.suppressed});

/** Every number of a composite, plus its warnings and verdict. */
function groupCapture(g: SparseGroupResult): Record<string, unknown> {
  return {
    groupKey: g.groupKey, route: g.route, topology: g.topology,
    aucLast: num(g.aucLast), aucSe: num(g.aucSe), aucDf: num(g.aucDf),
    aucCi: [num(g.aucCi[0]), num(g.aucCi[1])], aucCiMethod: g.aucCiMethod,
    cmax: num(g.cmax), tmax: num(g.tmax), aucInf: num(g.aucInf), lambdaZ: num(g.lambdaZ),
    halfLife: num(g.halfLife), cl: num(g.cl), vz: num(g.vz), mrt: num(g.mrt), vss: num(g.vss),
    clAbs: num(g.clAbs), vzAbs: num(g.vzAbs), vssAbs: num(g.vssAbs), pctExtrap: num(g.pctExtrap),
    lambdaZR2: num(g.lambdaZR2), lambdaZAdjR2: num(g.lambdaZAdjR2), spanRatio: num(g.spanRatio),
    lambdaZNPoints: num(g.lambdaZNPoints), verdict: g.acceptance.verdict,
    bootstrapAucExploratory: ci(g.bootstrapAucExploratory), bootstrapCmax: ci(g.bootstrapCmax),
    bootstrapHalfLife: ci(g.bootstrapHalfLife), bootstrapCl: ci(g.bootstrapCl),
    warnings: g.warnings.map((w) => ({code: w.code, message: w.message})),
  };
}

interface GoldenRun {
  readonly groups: Record<string, unknown>[];
  readonly fingerprints: string[];
}
interface SparseIvGolden {
  readonly sciCompVersion?: string;
  readonly runs?: Record<string, GoldenRun>;
}

/** The golden's three runs: the IV fixture as IV bolus, the PO mouse fixture as PO and as IV bolus. */
async function goldenRuns(): Promise<Record<string, GoldenRun>> {
  const iv = await loadSparseFrame('07_iv_bolus_sparse.csv');
  const mouse = await loadSparseFrame('04_mouse_sparse_destructive.csv');
  const runs: Record<string, SparseNcaResult> = {
    'iv-fixture IV-bolus': runSparse(iv, 'IV-bolus', 1e-6),
    'mouse PO': runSparse(mouse, 'PO', 0.001),
    'mouse IV-bolus': runSparse(mouse, 'IV-bolus', 0.001),
  };
  const out: Record<string, GoldenRun> = {};
  for (const [name, r] of Object.entries(runs))
    out[name] = {groups: r.groups.map(groupCapture), fingerprints: sparseCompositeUnits(r).map((u) => u.fingerprint)};
  return out;
}

function toBase64(s: string): string {
  const bytes = new TextEncoder().encode(s);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

const SPARSE_IV_GOLDEN = GOLDEN as SparseIvGolden;

interface IvReference {
  composites: Array<{dose_mg_kg: number; c0: number; c0_method: string; sparse_auclast_c0: number}>;
}

/** The dense run's AUClast on the composite, from its own AUCinf: AUCinf − Clast/λz (Clast = the last
 *  positive composite mean the BLQ rule kept). NaN without λz. */
function denseAucLast(g: SparseGroupResult): number {
  const clast = [...g.composite.timepoints].reverse().find((t) => t.n > 0 && t.nBlq / t.n <= 0.5 && t.mean > 0);
  return clast === undefined ? NaN : g.aucInf - clast.mean / g.lambdaZ;
}

const relDiff = (a: number, b: number): number => Math.abs(a - b) / Math.abs(b);
const groupOf = (r: SparseNcaResult, dose: number): SparseGroupResult =>
  r.groups.find((g) => g.doseLevel.value === dose)!;

/** The golden capture of one run's composite `groupKey`. */
function goldenGroup(run: string, key: string): Record<string, unknown> {
  const g = SPARSE_IV_GOLDEN.runs![run].groups.find((x) => x['groupKey'] === key);
  if (g === undefined) throw new Error(`golden ${run}: no composite ${key}`);
  return g;
}
const codesOf = (g: Record<string, unknown>): string[] =>
  (g['warnings'] as Array<{code: string}>).map((w) => w.code);

category('Adapter: sparse IV-bolus anchor', () => {
  let iv: DG.DataFrame;
  let mouse: DG.DataFrame;
  let ref: IvReference;
  before(async () => {
    iv = await loadSparseFrame('07_iv_bolus_sparse.csv');
    mouse = await loadSparseFrame('04_mouse_sparse_destructive.csv');
    ref = JSON.parse(await grok.dapi.files.readAsText(
      `${FIXTURE_PATH_PREFIX}/07_iv_bolus_sparse-reference.json`)) as IvReference;
  });

  test('0.11.0 golden: captured and committed', async () => {
    if (SPARSE_IV_GOLDEN.runs === undefined) {
      const capture = {sciCompVersion: '0.11.0', runs: await goldenRuns()};
      return `CAPTURE ${toBase64(JSON.stringify(capture))}`;
    }
    expect(SPARSE_IV_GOLDEN.sciCompVersion, '0.11.0', 'the golden was captured on sci-comp 0.11.0');
    return 'golden present';
  }, {timeout: TIMEOUT});

  test('AC-3.1: IV AUClast = the dense AUClast (1e-9) = PKNCA auciv on Ĉ0 (0.1 %)', async () => {
    const res = runSparse(iv, 'IV-bolus', 1e-6);
    for (const r of ref.composites) {
      const g = groupOf(res, r.dose_mg_kg);
      const d = `IV ${r.dose_mg_kg} mg/kg`;
      expect(relDiff(g.aucLast, denseAucLast(g)) < 1e-9, true,
        `${d}: AUClast ${g.aucLast} vs dense ${denseAucLast(g)}`);
      expect(relDiff(g.aucLast, r.sparse_auclast_c0) < 1e-3, true,
        `${d}: AUClast ${g.aucLast} vs PKNCA ${r.sparse_auclast_c0}`);
    }
  }, {timeout: TIMEOUT});

  // AC-3.1b: parity is by shared inputs (`compositeProfileArrays` + one chain), not by construction —
  // the dense side sees the UNFILTERED composite. Measured on BLQ-edge variants of IV composite 2.
  test('AC-3.1b: BLQ-edge IV composites — parity, and the one measured exception', async () => {
    const base = runSparse(iv, 'IV-bolus', 1e-6);
    const variant = (edit: (rows: number[], df: DG.DataFrame) => void): SparseGroupResult => {
      const df = iv.clone();
      const rows = Array.from({length: df.rowCount}, (_, i) => i).filter((i) => df.col('Dose_mg_kg')!.get(i) === 2);
      edit(rows, df);
      return groupOf(runSparse(df, 'IV-bolus', 1e-6), 2);
    };
    const blqAt = (df: DG.DataFrame, rows: number[], t: number, k: number): void => {
      const at = rows.filter((i) => Math.abs(df.col('NominalTime_hr')!.get(i) - t) < 1e-9).slice(0, k);
      for (const i of at) {df.col('BLQflag')!.set(i, true); df.col('Conc')!.set(i, 0);}
    };
    const addRows = (df: DG.DataFrame, rows: number[], t: number): void => {
      for (let k = 0; k < 3; k++) {
        const i = df.rowCount;
        df.rows.addNew();
        for (const c of df.columns.toList()) if (!c.isNone(rows[k])) c.set(i, c.get(rows[k]));
        df.col('MouseID')!.set(i, `PRE${t}_${k}`); df.col('NominalTime_hr')!.set(i, t);
        df.col('Conc')!.set(i, 0); df.col('BLQflag')!.set(i, true);
      }
    };
    const parity: Record<string, SparseGroupResult> = {
      'BLQ-majority mid (2 h)': variant((rows, df) => blqAt(df, rows, 2, 2)),
      'BLQ-majority last (24 h)': variant((rows, df) => blqAt(df, rows, 24, 2)),
      'BLQ t = 0 group': variant((rows, df) => addRows(df, rows, 0)),
    };
    for (const [name, g] of Object.entries(parity)) {
      expect(relDiff(g.aucLast, denseAucLast(g)) < 1e-9, true,
        `${name}: AUClast ${g.aucLast} vs dense ${denseAucLast(g)}`);
      expect(relDiff(g.c0!.value, g.c0Provenance!.value) < 1e-12, true, `${name}: one C0`);
    }
    // The BLQ t = 0 group is not integrated: the numbers equal the unmodified composite's.
    expect(parity['BLQ t = 0 group'].aucLast, groupOf(base, 2).aucLast, 'a pre-dose BLQ group changes nothing');
    // MEASURED EXCEPTION (rule 16, recorded in METHOD-24): a t < 0 group. `sparseAuc` drops it, the
    // dense `computeNca` on the unfiltered composite does not, so the closed-form AUClast keeps the
    // unmodified number while the dense side moves.
    const pre = variant((rows, df) => addRows(df, rows, -0.5));
    expect(pre.aucLast, groupOf(base, 2).aucLast, 't < 0: the closed-form AUClast ignores the pre-dose group');
    // Pinned KNOWN DEFECT (TODO IMPL-GAP-SPARSE-PREDOSE-NEGATIVE-TIME, pre-existing on every route): the
    // dense run prepends (0, C0) before t = −0.5 and integrates a negative-width segment — measured AUCinf
    // 20.84 → 17.04. When it is fixed this assertion fails on purpose: replace it with parity.
    expect(relDiff(denseAucLast(pre), pre.aucLast) > 0.1, true, 't < 0: the dense side still differs (known defect)');
    return `t<0: AUClast ${pre.aucLast} · dense AUClast ${denseAucLast(pre)} · AUCinf ${pre.aucInf} ` +
      `(unmodified AUCinf ${groupOf(base, 2).aucInf})`;
  }, {timeout: TIMEOUT});

  test('AC-3.3: IV AUCinf / λz / CL / Vz / MRT / Vss byte-identical to the 0.11.0 golden', async () => {
    for (const [run, res] of [['iv-fixture IV-bolus', runSparse(iv, 'IV-bolus', 1e-6)],
      ['mouse IV-bolus', runSparse(mouse, 'IV-bolus', 0.001)]] as const) {
      for (const g of res.groups) {
        const was = goldenGroup(run, g.groupKey);
        const now = groupCapture(g);
        for (const k of ['aucInf', 'lambdaZ', 'halfLife', 'cl', 'vz', 'mrt', 'vss', 'pctExtrap', 'cmax', 'tmax',
          'lambdaZAdjR2', 'lambdaZNPoints', 'verdict', 'bootstrapCmax', 'bootstrapHalfLife', 'bootstrapCl'])
          expect(JSON.stringify(now[k]), JSON.stringify(was[k]), `${run} ${g.groupKey} ${k}`);
      }
    }
  }, {timeout: TIMEOUT});

  test('AC-3.5: PO mouse — every field byte-identical to 0.11.0 but the terminal note', async () => {
    for (const g of runSparse(mouse, 'PO', 0.001).groups) {
      const was = goldenGroup('mouse PO', g.groupKey);
      const now = groupCapture(g);
      for (const k of Object.keys(was)) {
        if (k === 'warnings') continue;
        expect(JSON.stringify(now[k]), JSON.stringify(was[k]), `PO ${g.groupKey} ${k}`);
      }
      // Every warning but the terminal note, code AND message, unchanged.
      type W = {code: string; message: string};
      const other = (g2: Record<string, unknown>): W[] =>
        (g2['warnings'] as W[]).filter((w) => w.code !== 'SPARSE_TERMINAL_OVEREST');
      expect(JSON.stringify(other(now)), JSON.stringify(other(was)), `PO ${g.groupKey} warnings`);
      expect(g.c0, null, 'no C0 off IV bolus');
    }
  }, {timeout: TIMEOUT});

  test('AC-4.1 / 4.3: C0_FALLBACK on the rising-pair composite only; one C0 per row', async () => {
    const res = runSparse(iv, 'IV-bolus', 1e-6);
    for (const r of ref.composites) {
      const g = groupOf(res, r.dose_mg_kg);
      const has = g.warnings.some((w) => w.code === 'C0_FALLBACK');
      expect(has, r.c0_method === 'c1', `IV ${r.dose_mg_kg} mg/kg (${r.c0_method}): C0_FALLBACK`);
      expect(relDiff(g.c0Provenance!.value, g.c0!.value) < 1e-12, true, `IV ${r.dose_mg_kg}: dense C0 = anchor`);
      expect(g.c0Provenance!.method, g.c0!.method, `IV ${r.dose_mg_kg}: one method`);
    }
    expect(res.parameterTable.col('NOTES')!.get(res.groups.findIndex((g) => g.doseLevel.value === 3))
      .includes('C0 not back-extrapolated'), true, 'the short note reaches Notes');
    for (const g of runSparse(mouse, 'PO', 0.001).groups)
      expect(g.warnings.some((w) => w.code === 'C0_FALLBACK'), false, `PO ${g.groupKey}: never`);
  }, {timeout: TIMEOUT});

  test('AC-4.2: C0_EXTRAP = the PKNCA c0; its tooltip share; hidden on the PO study', async () => {
    const res = runSparse(iv, 'IV-bolus', 1e-6);
    const col = res.parameterTable.col('C0_EXTRAP')!;
    res.groups.forEach((g, i) => {
      const r = ref.composites.find((x) => x.dose_mg_kg === g.doseLevel.value)!;
      expect(relDiff(col.get(i), r.c0) < 1e-6, true, `IV ${r.dose_mg_kg}: C0_EXTRAP ${col.get(i)} vs PKNCA ${r.c0}`);
      expect(g.c0!.method, r.c0_method, `IV ${r.dose_mg_kg}: method`);
      const line = c0ShareLine(g.c0!.method, g.c0Provenance!.pctAucBackExtrap);
      expect(line?.textContent ?? '',
        `back-extrapolated: ${g.c0Provenance!.pctAucBackExtrap.toFixed(1)} % of AUC₀–∞`, `IV ${r.dose_mg_kg}: tip`);
    });
    const visible = (r: SparseNcaResult): boolean => {
      const grid = DG.Viewer.grid(r.parameterTable);
      configureSparseNcaGrid(grid);
      return grid.columns.byName('C0_EXTRAP')!.visible;
    };
    // A measured dose-time C0 has nothing extrapolated: the line is omitted, never `0 %`.
    expect(c0ShareLine('observed', 0), null, 'observed C0: no share line');
    expect(visible(res), true, 'shown on an IV-bolus study');
    const po = runSparse(mouse, 'PO', 0.001);
    expect(visible(po), false, 'hidden on the PO study');
    expect(po.parameterTable.col('C0_EXTRAP')!.isNone(0), true, 'blank off IV bolus');
  }, {timeout: TIMEOUT});

  // AC-4.4: the decision fingerprint moves only by the ratified F5 change. Reconstructed from the
  // golden's own fit numbers and warning codes: with the 0.11.0 filter it IS the golden fingerprint
  // (the reconstruction is faithful); with today's filter it IS today's fingerprint — so the only
  // difference is SPARSE_TERMINAL_OVEREST leaving the fingerprint (fingerprint principle (A)). The
  // AUClast change (F3) and C0_FALLBACK / C0_EXTRAP (F4) move no fingerprint.
  test('AC-4.4: IV fingerprints change only by the terminal note leaving them (A)', async () => {
    for (const [run, res] of [['iv-fixture IV-bolus', runSparse(iv, 'IV-bolus', 1e-6)],
      ['mouse IV-bolus', runSparse(mouse, 'IV-bolus', 0.001)],
      ['mouse PO', runSparse(mouse, 'PO', 0.001)]] as const) {
      const now = sparseCompositeUnits(res).map((u) => u.fingerprint);
      res.groups.forEach((g, i) => {
        const was = goldenGroup(run, g.groupKey);
        const fp = (drop: ReadonlySet<string>): string => computeDecisionFingerprint({
          points: g.rawPoints.map((p) => [String(p.nominalTime), p.blq ? 'BLQ' : String(p.conc)] as const),
          dose: String(g.doseLevel.value), route: '', pointsUsedTimes: [],
          lambdaZ: was['lambdaZ'] as number, adjR2: was['lambdaZAdjR2'] as number,
          aucInf: was['aucInf'] as number, pctExtrap: was['pctExtrap'] as number,
          verdict: was['verdict'] as string, flagCodes: g.acceptance.flagCodes,
          warnings: codesOf(was).filter((c) => !/^SPARSE_BOOTSTRAP_/.test(c) && !drop.has(c))
            .map((code) => ({code, severity: 'info'})),
        });
        const old = new Set(['SPARSE_LLOQ_VARIES', 'SPARSE_IV_BOLUS_C0_ANCHOR']);
        expect(fp(old), SPARSE_IV_GOLDEN.runs![run].fingerprints[i], `${run} ${g.groupKey}: reconstruction`);
        expect(fp(new Set([...old, 'SPARSE_TERMINAL_OVEREST'])), now[i], `${run} ${g.groupKey}: only (A) moved it`);
      });
    }
  }, {timeout: TIMEOUT});

  test('AC-5.1 / 5.2: the terminal note with t½ — IV 1, 2 fire, dense tail silent; gains and losses', async () => {
    const res = runSparse(iv, 'IV-bolus', 1e-6);
    const fires = (g: SparseGroupResult): boolean => g.warnings.some((w) => w.code === 'SPARSE_TERMINAL_OVEREST');
    expect(fires(groupOf(res, 1)), true, 'IV 1 mg/kg (12 → 24 h gap): fires');
    expect(fires(groupOf(res, 2)), true, 'IV 2 mg/kg (8 → 24 h gap): fires');
    expect(fires(groupOf(res, 4)), false, 'IV 4 mg/kg (dense tail, 2 h gap): silent');
    const changes: string[] = [];
    for (const [run, r] of [['iv-fixture IV-bolus', res], ['mouse PO', runSparse(mouse, 'PO', 0.001)],
      ['mouse IV-bolus', runSparse(mouse, 'IV-bolus', 0.001)]] as const) {
      for (const g of r.groups) {
        const was = codesOf(goldenGroup(run, g.groupKey)).includes('SPARSE_TERMINAL_OVEREST');
        if (was !== fires(g)) changes.push(`${run} ${g.groupKey}: ${was ? 'loses' : 'gains'}`);
      }
    }
    // Measured (rule 16): three composites lose the note, none gains it. The dense-tail IV composite
    // (2 h last gap < 2 × t½ 2.1 h) and the mouse 10 mg/kg composite on both routes: its 24 h mean is
    // all-BLQ, so the last measurable gap is 8 → 12 h = 4 h < 2 × t½ 3.1 h.
    expect(changes.join('; '), 'iv-fixture IV-bolus DOSE=4: loses; mouse PO DOSE=10: loses; ' +
      'mouse IV-bolus DOSE=10: loses', 'the measured change list');
    const excess = [1, 2].map((d) => groupOf(res, d).terminalExcessPct);
    for (const [k, d] of [1, 2].entries()) {
      expect(Number.isFinite(excess[k]) && excess[k] > 0, true, `IV ${d}: excess % stated`);
      expect(res.parameterTable.col('NOTES')!.get(res.groups.indexOf(groupOf(res, d)))
        .includes(`terminal AUC may overestimate (≈ ${excess[k].toFixed(1)} %)`), true, `IV ${d}: short note`);
    }
    return `excess: IV 1 mg/kg ${excess[0].toFixed(2)} %, IV 2 mg/kg ${excess[1].toFixed(2)} %`;
  }, {timeout: TIMEOUT});

  // AC-3.6: one sparse path (BUG-19). `ncaCompute` on the IV fixture (auto mapping) gives each
  // composite the app's C0-anchored AUC_LAST and its C0_EXTRAP.
  test('AC-3.6: ncaCompute IV-bolus composites — the app\'s AUC_LAST and C0_EXTRAP', async () => {
    const df = await loadFixture('07_iv_bolus_sparse.csv');
    const det = detectPipelineMapping(df);
    expect(det.mapping !== null, true, det.issues.join('; '));
    const out = computePipeline(df, JSON.stringify({...det.mapping!, blq: 'BLQ'}), '');
    const app = runSparse(iv, 'IV-bolus', 1e-6);
    const comp = Array.from({length: out.rowCount}, (_, i) => i)
      .filter((i) => out.col('SUBJECT')!.getString(i) === COMPOSITE_SUBJECT);
    expect(comp.length, app.groups.length, 'one composite row per dose group');
    for (const i of comp) {
      const dose = out.col('DOSE')!.get(i) as number;
      const g = groupOf(app, dose);
      expect(out.col('ROUTE')!.getString(i), 'IV-bolus', `${dose} mg/kg: route`);
      // 1e-6, not 1e-9: this file's own frame (`loadSparseFrame`, `DG.DataFrame.fromCsv`) holds the
      // nominal time as float32 (0.083 → 0.0829999968), while `loadFixture` — the app's and the
      // pipeline's CSV path — keeps float64. Measured 8e-9 on C0 (1 mg/kg); the pipeline value equals the
      // PKNCA oracle's c0 to its 12 digits. The loader stays: the 0.11.0 golden was captured with it.
      for (const [col, want] of [['AUC_LAST', g.aucLast], ['C0_EXTRAP', g.c0!.value]] as const) {
        const got = out.col(col)!.get(i) as number;
        expect(relDiff(got, want) < 1e-6, true, `${dose} mg/kg: pipeline ${col} ${got} vs app ${want}`);
      }
      const r = ref.composites.find((x) => x.dose_mg_kg === dose)!;
      expect(relDiff(out.col('C0_EXTRAP')!.get(i) as number, r.c0) < 1e-9, true, `${dose} mg/kg: pipeline C0 = PKNCA`);
    }
  }, {timeout: TIMEOUT});

  test('AC-5.3: no λz → the concentration-only check and the "no t½ supplied" message', async () => {
    // One composite, Cmax at 1 h and a single point after it: no λz, terminal mean < 20 % Cmax.
    const t = [0.5, 0.5, 1, 1, 8, 8]; const c = [5, 5.2, 10, 10.4, 1, 1.1];
    const df = DG.DataFrame.fromColumns([
      DG.Column.fromList(DG.COLUMN_TYPE.STRING, 'Animal', t.map((_, i) => `A${i}`)),
      DG.Column.fromFloat64Array('NomTime', Float64Array.from(t)),
      DG.Column.fromFloat64Array('Conc', Float64Array.from(c)),
      DG.Column.fromFloat64Array('Dose', Float64Array.from(t.map(() => 10))),
    ]);
    const g = computeSparseNca(df, {concCol: 'Conc', nominalTimeCol: 'NomTime', animalIdCol: 'Animal',
      doseCol: 'Dose', groupCol: 'Dose', route: 'PO', bootstrapIterations: 50}).groups[0];
    expect(Number.isNaN(g.halfLife), true, 'no λz');
    const w = g.warnings.find((x) => x.code === 'SPARSE_TERMINAL_OVEREST');
    expect(w !== undefined && w.message.includes('no t½ supplied'), true, 'the fallback still fires and says so');
  }, {timeout: TIMEOUT});
});
